// Let's get all games for months 06, 07, 08 of 2026 (or check 2025/2024 to verify stadiums and schedule structure)
const stadiumsAndGames = await browserjs(tabId, async () => {
  const parseCurrentTable = () => {
    const rows = Array.from(document.querySelectorAll('.tbl-type06 tbody tr, table.tbl tbody tr'));
    let currentDate = "";
    const games = [];
    for (const r of rows) {
      const dateTd = r.querySelector('.day');
      if (dateTd && dateTd.textContent.trim()) {
        currentDate = dateTd.textContent.trim();
      }
      const time = r.querySelector('.time')?.textContent.trim();
      const play = r.querySelector('.play')?.textContent.trim();
      // stadium is usually in the second to last or last columns
      const tds = Array.from(r.querySelectorAll('td')).map(td => td.textContent.trim());
      games.push({ date: currentDate, rowText: tds.join(' | ') });
    }
    return games;
  };

  // Check month 07
  $('#ddlMonth').val('07').trigger('change');
  await new Promise(r => setTimeout(r, 1500));
  const julyGames = parseCurrentTable();

  // Check month 06
  $('#ddlMonth').val('06').trigger('change');
  await new Promise(r => setTimeout(r, 1500));
  const juneGames = parseCurrentTable();

  // Check month 08
  $('#ddlMonth').val('08').trigger('change');
  await new Promise(r => setTimeout(r, 1500));
  const augustGames = parseCurrentTable();

  return { juneGames: juneGames.slice(0, 10), julyGames: julyGames.slice(0, 10), augustGames: augustGames.slice(0, 10), totalJuly: julyGames.length };
