Arguments: {"cwd":null,"title":"Extract all summer games and unique stadiums","code":"const tabId = 787783793;

const stadiumsData = await browserjs(tabId, async () => {
  const getGamesForMonth = async (m) => {
    $('#ddlMonth').val(m).trigger('change');
    await new Promise(r => setTimeout(r, 1200));
    const rows = Array.from(document.querySelectorAll('.tbl-type06 tbody tr, table.tbl tbody tr'));
    let curDate = "";
    const list = [];
    for (const r of rows) {
      const dateTd = r.querySelector('.day');
      if (dateTd && dateTd.textContent.trim()) {
        curDate = dateTd.textContent.trim();
      }
      const tds = Array.from(r.querySelectorAll('td')).map(td => td.textContent.trim());
      // td format: [date, time, matchup, review, highlight, tv, ..., stadium, note]
      // or similar
      const stadium = tds.length >= 2 ? tds[tds.length - 2] : "";
      const time = r.querySelector('.time')?.textContent.trim() || tds[1];
      const play = r.querySelector('.play')?.textContent.trim() || tds[2];
      list.push({ date: curDate, time, play, stadium, full: tds.join(' | ') });
    }
    return list;
  };

  const june = await getGamesForMonth('06');
  const july = await getGamesForMonth('07');
  const aug = await getGamesForMonth('08');

  const all = [...june, ...july, ...aug];
  const stadiums = new Set();
  all.forEach(g => {
    if (g.stadium) stadiums.add(g.stadium);
  });

  return {
    uniqueStadiums: Array.from(stadiums),
    allCount: all.length,
    sample: all.slice(0, 5)
  };
});

console.log("Unique stadiums in summer (June-August):", stadiumsData.uniqueStadiums);
console.log("Sample game:", stadiumsData.sample);
"}
